class UpupidaeStyle extends HTMLElement{connectedCallback(){const e=this.getAttribute("href");if(!e)return;if(!document.head.querySelector('link[rel="stylesheet"][href="'+CSS.escape(e)+'"]')){const t=document.createElement("link");t.rel="stylesheet",t.href=e,document.head.appendChild(t)}this.remove()}}customElements.define("upupidae-style",UpupidaeStyle);
